'use strict';

var Complex128 = require( '@stdlib/complex/float64/ctor' );
var zrotg = require( './../lib' );

function example( za, zb ) {
	var out = zrotg( za, zb );

	console.log( 'za =', za.toString() );
	console.log( 'zb =', zb.toString() );
	console.log('ans =', out.toString());
	console.log( '-----------------------------' );
}

/* 1 */
example(new Complex128( 5, 6 ), new Complex128( 0, 0 ));

/* 2 */
example(new Complex128( 4, 3 ), new Complex128( 0, 0 ));

/* 3 */
example(new Complex128( 1, 3 ), new Complex128( 2, 4 ));

/* 4 */
example(new Complex128( 2, 1 ), new Complex128( 0, 0 ));

/* 5 */
example(new Complex128( -3, 4 ), new Complex128( 0, 0 ));

/* 6 */
example(new Complex128( 0, 0 ), new Complex128( 5, 12 ));

/* 7 */
example(new Complex128( 3, 4 ), new Complex128( 1, 0 ));

/* 8 */
example(new Complex128( 6, -2 ), new Complex128( 3, 1 ));

/* 9 */
example(new Complex128( -2, 5 ), new Complex128( 4, -3 ));

/* 10 */
example(new Complex128( 1, -1 ), new Complex128( 1, 1 ));
